<script setup lang="ts">
const PAGE_SIZE=25
const search=ref("");const status=ref("");const offset=ref(0)
const query=computed(()=>({search:search.value||undefined,status:status.value||undefined,offset:String(offset.value),limit:String(PAGE_SIZE)}))
const {data,pending,error,refresh}=await useFetch<any>("/api/provider/identities",{query})
watch([search,status],()=>{offset.value=0})
</script>
<template><div class="page-stack"><div class="page-heading"><div><p class="eyebrow">IDENTITY</p><h1>Identities</h1><p>Provider-wide identity directory backed by Saiwaly IAM™.</p></div><button class="secondary-button" @click="refresh()">Refresh</button></div><section class="panel"><div class="admin-filters"><input v-model="search" placeholder="Search email or identity"><select v-model="status"><option value="">All statuses</option><option>active</option><option>suspended</option></select></div><div v-if="pending" class="loading-panel">Loading identities…</div><div v-else-if="error" class="error-panel"><strong>Unable to load identities</strong><p>{{error.message}}</p></div><div v-else-if="data?.items?.length" class="table-wrap"><table><thead><tr><th>Email</th><th>Status</th><th>Verified</th><th>Identity</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.userId"><td><NuxtLink :to="`/identities/${item.userId}`" class="table-link">{{item.email}}</NuxtLink></td><td><span class="pill" :class="{'pill--good':item.status==='active'}">{{item.status}}</span></td><td>{{item.emailVerified?'Yes':'No'}}</td><td class="mono">{{item.userId}}</td></tr></tbody></table></div><div v-else class="empty-state"><strong>No identities found</strong><p>Adjust the Provider search filters.</p></div><AppPagination :total="data?.total??0" :offset="offset" :limit="PAGE_SIZE" @change="offset=$event" /></section></div></template>
